\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22  (161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  -162\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Sermones de sanctis}}\plain \f1\lang1033\fs22   (S33-S59)
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\super\lang1033\fs24 252\plain \f1\lang1033\fs22  (161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) \plain \f1\i\lang1033\fs22  Ingressa Bethsabee in cubiculum Salomonis\plain \f1\lang1033\fs22   (vgl. III Rg 1,15). \plain \f1\i\lang1033\fs22  Salomon pacificus Christus. Bethsabee interpretatur puteus sanitatis et signat beatam virginem, que sanat omnem hominem\plain \f1\lang1033\fs22  ... Nr. 204 (S59); weitere Predigten aus Graz, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Ms. 1255}}\plain \f1\lang1033\fs22 : \plain \f1\super\lang1033\fs24 253\plain \f1\lang1033\fs22  Nr. 178 (S33), \plain \f1\super\lang1033\fs24 254\plain \f1\lang1033\fs22  Nr. 197 (S54), \plain \f1\super\lang1033\fs24 255\plain \f1\lang1033\fs22  Nr. 198 (S54).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

