\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22  (162\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  -163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Sermones de commune}}\plain \f1\lang1033\fs22   (C2, C11)
