\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat18 Sp\u228 \'e4tgotischer, stark abgeriebener Holzdeckelband}}\plain \f1\lang1033\fs20   mit {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat18 Leder\u252 \'fcberzug}}\plain \f1\lang1033\fs20   aus gef\u228 \'e4rbtem S\u228 \'e4mischleder (vgl. Karl \plain \f1\scaps\lang1033\fs20 J\plain \f1\scaps\lang1033\fs20 \u228 \'e4\plain \f1\scaps\lang1033\fs20 ckel\plain \f1\lang1033\fs20 , Alte Techniken des Buchbinderhandwerks in der modernen Schriftgutrestaurierung, in: Bibliotheksforum Bayern 6 (1978), S. 218), darauf Streicheisenlinien und mindestens 2 nicht identifizierte Einzelstempel. Spuren von 2 Schlie\u223 \'dfen. Titelschilder auf dem Vorderdeckel und dem R\u252 \'fccken (\plain \f1\i\lang1033\fs20  Sermones Anthonii Parmensis\plain \f1\lang1033\fs20 ). Reste von 4 Signaturschildchen (verblasst).}

