\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  180\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -190\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24   \plain \f1\lang1033\fs22   \plain \f1\b\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Georgius Tudel (?)}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tractatus de extremo iudicio}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\i\lang1033\fs24  \u8250 \'9bIncipit tractatus de extremo iudicio egregii doctoris sacre theologie Magistri Thome Haselbach in vniversitate Wiennensi\u8249 \'8b Hic est vere propheta\plain \f1\lang1033\fs24  ... (Io 6,14). \plain \f1\i\lang1033\fs24  Generale iudicium est futurum in quo iudicabuntur omnes homines secundum animas et corpora iuxta eorum merita \plain \f1\lang1033\fs24 ..., (185\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  \u8250 \'9bSequitur de processu iudicis in extremo et vltimo iudicio\u8249 \'8b\plain \f1\lang1033\fs24 , (189\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  \u8250 \'9bQuestio de iudicio finali\u8249 \'8b\plain \f1\lang1033\fs24 , (190\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  \u8250 \'9bDe quibus oportet reddere rationem\u8249 \'8b\plain \f1\lang1033\fs24 , (190\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24  sacrilegus est et horum omnium reus in iudicio\plain \f1\lang1033\fs24  || Abbruch am Seitenende, danach 3 Bll. herausgetrennt.
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20  Text unvollst\u228 \'e4ndig. Hier wird der Traktat Thomas Ebendorfer zugewiesen, in der Parallel\u252 \'fcberlieferung (Seitenstetten, StiftsB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod 220}}\plain \f1\lang1033\fs20 , 243\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -302\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20   und Wien, \u214 \'d6NB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cvp 14352}}\plain \f1\lang1033\fs20 , 61\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -105\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 ) ist ein Wiener Kollege Ebendorfers, Georg Tudel de Giengen (\u8224 \'86 nach 1465) als Verfasser genannt; zur Verfasserschaft vgl. Hans-Jochen \plain \f1\scaps\lang1033\fs20 Schiewer\plain \f1\lang1033\fs20 , in: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20  VL 11 (2004), Sp. 1567f. \endash  Hs. erw\u228 \'e4hnt bei Alphons \plain \f1\scaps\lang1033\fs20 Lhotsk\plain \f1\scaps\lang1033\fs20 y\plain \f1\lang1033\fs20 , Thomas Ebendorfer, Stuttgart 1957, S. 72, Nr. 33 (Folioangaben abweichend)\plain \f1\lang1033\fs22 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  191\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -199\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24     {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Sermones de tempore}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 (191\plain \f1\super\lang1033\fs24 ra-va\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24  Dominica letare sermo bonus\plain \f1\lang1033\fs24  \u8249 \'8b. \plain \f1\i\lang1033\fs24  Est puer\plain \f1\lang1033\fs24   (Io 6,9). \plain \f1\i\lang1033\fs24  Augustinus: Non est magnum pascere ventres\plain \f1\lang1033\fs24  ... \plain \f1\scaps\lang1033\fs24 Schneyer,\plain \f1\lang1033\fs24   Repertorium 3, S. 225, Nr. 52. \endash  (191\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -192\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 1, S. 212, Nr. 844. \endash  (192\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -195\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  Risus dolore\plain \f1\lang1033\fs24  ... (Prv 14,13). \plain \f1\i\lang1033\fs24  Ecclesia sancta hodie facit duplicem processionem\plain \f1\lang1033\fs24  ... \endash  (193\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  -195\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 2, S. 643, Nr. 60 (Schluss abweichend, Textl\u252 \'fccke infolge partiellen Blattverlustes). \endash  (196\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 2, S. 644, Nr. 68. \endash  (197\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  Vado ad eum\plain \f1\lang1033\fs24   (Io 16,5). \plain \f1\i\lang1033\fs24  Christus post cenam discipulos suos tripliciter est consolatus\plain \f1\lang1033\fs24  ... (Ende unvollst\u228 \'e4ndig). \endash  (197\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) \plain \f1\scaps\lang1033\fs24 Schneyer\plain \f1\lang1033\fs24 , Repertorium 2, S. 645\plain \f1\lang1033\fs22 ,\plain \f1\lang1033\fs24   Nr. 78. \endash  (198\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24  -199\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  Si quis diligit\plain \f1\lang1033\fs24  ... (Io 14,23). \plain \f1\i\lang1033\fs24  Dicit beatus Augustinus: Veniunt ad nos Pater et filius et spiritus sanctus\plain \f1\lang1033\fs24  ... \endash  196\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 199\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   leer.
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs20  Sermones f\u252 \'fcr die Osterzeit (Letare-Pentecoste), zumeist verk\u252 \'fcrzt oder unvollst\u228 \'e4ndig, z. T. mit entsprechendem Hinweis (u. a. 191\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20   \plain \f1\i\lang1033\fs20  Pro secunda parte dic aliqua de preceptis et conclude\plain \f1\lang1033\fs20 ); einige Predigten mit sehr kurzen deutschen Einsch\u252 \'fcben (191\plain \f1\super\lang1033\fs20 ra\plain \f1\lang1033\fs20 , 198\plain \f1\super\lang1033\fs20 rab\plain \f1\lang1033\fs20 , 199\plain \f1\super\lang1033\fs20 rab\plain \f1\lang1033\fs20 ).}

