\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  247\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -250\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17  Guilelmus Durantis}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Repertorium aureum iuris}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  (Auszug X. 5. 38)}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24  Repertorium Rubrice de pe\plain \f1\lang1033\fs24  [nitentiis] \plain \f1\i\lang1033\fs24  et re\plain \f1\lang1033\fs24  [missionibus] \plain \f1\i\lang1033\fs24  Gwilhelmi\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  Durantis\plain \f1\lang1033\fs24  \u8249 \'8b \plain \f1\i\lang1033\fs24  An circumstancie vel dignitas aggravant peccatum\plain \f1\lang1033\fs24  ...\endash ... \plain \f1\i\lang1033\fs24  In septima de hoc quod est supra ubi usque ad quod tempus. Et sic est finis etc.
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\scaps\lang1033\fs20 Bloomfield\plain \f1\lang1033\fs20 , Incipits 410. \endash  Druck: GW 9145 C\plain \f1\super\lang1033\fs20 va\plain \f1\lang1033\fs20  -CII\plain \f1\super\lang1033\fs20 vb\plain \f1\lang1033\fs20 . \endash  Zur Parallel\u252 \'fcberlieferung s. o. 208\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 .}

