\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  251\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -259\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24     {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Johannes de Auerbach (?)}}\plain \f1\b\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Tractatus de restitutionibus}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24  Tractatus de restitutionibus et qualiter restitucio sit facienda\plain \f1\lang1033\fs24  \u8249 \'8b \plain \f1\i\lang1033\fs24  Quoniam sicut scriptum est Mendaces sunt filii hominum \plain \f1\lang1033\fs24  (Ps. 64,10)\plain \f1\i\lang1033\fs24   \plain \f1\lang1033\fs24 ...\endash ... \plain \f1\i\lang1033\fs24  vel remissio perire faciat quos discreta poterat equitas reuocare\plain \f1\lang1033\fs24 .
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 
