\pard\fi0\li0\tx5700\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (169\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  -171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Orationes ad angelos, apostolos et martyres}}
\par \pard\fi0\li0\tx5700\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\tx5700\ql\ri0\sb0\sa60\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sancte Michael archangele, domini nostri Ihesv Christi}}\plain \f1\i\lang1033\fs24 , qui in adiutorium uenisti\plain \f1\lang1033\fs24  ... Vgl. \plain \f1\scaps\lang1033\fs24 Leroquais\plain \f1\lang1033\fs24 , Les psautiers 2, S. 195; \plain \f1\scaps\lang1033\fs24 Wilmart\plain \f1\lang1033\fs24 , Auteurs spirituels, S. 212f. (Sp. 2). \endash  (170\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24  De sancto Iohanne baptista\plain \f1\lang1033\fs24  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Beate Iohannes baptista, precursor et martyr Christi uirgoque amabilis}}\plain \f1\i\lang1033\fs24 , obsecro te, ut intercedas pro me\plain \f1\lang1033\fs24  ... Vgl. \plain \f1\scaps\lang1033\fs24 Leroquais\plain \f1\lang1033\fs24 , Livres d\rquote heures 1, S. 35; \plain \f1\scaps\lang1033\fs24 Wilmart\plain \f1\lang1033\fs24 , Manuel, S. 284, Nr. 40; \plain \f1\scaps\lang1033\fs24 Turner\plain \f1\lang1033\fs24 , S. 378, Nr. 38. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24  Ad sanctum Petrum apostolum\plain \f1\lang1033\fs24  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sancte Petre, apostole electe dei, tu confessus es filium deum}}\plain \f1\i\lang1033\fs24   super te\plain \f1\lang1033\fs24  ... Vgl. \plain \f1\scaps\lang1033\fs24 Leroquais\plain \f1\lang1033\fs24 , Livres d\rquote heures 1, S. 35; \plain \f1\scaps\lang1033\fs24 Turner\plain \f1\lang1033\fs24 , S. 378, Nr. 39. \endash  (170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24  Ad sanctum Paulum\plain \f1\lang1033\fs24  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sancte Paule, uas electionis, quem dominus de celis ad se uocare}}\plain \f1\i\lang1033\fs24   dignatus est\plain \f1\lang1033\fs24  ... Vgl. \plain \f1\scaps\lang1033\fs24 Wilmart\plain \f1\lang1033\fs24 , Manuel, S. 285, Nr. 42; \plain \f1\scaps\lang1033\fs24 Turner\plain \f1\lang1033\fs24 , S. 378f., Nr. 40; \plain \f1\scaps\lang1033\fs24 Dell\plain \f1\scaps\lang1033\fs24 \rquote \plain \f1\scaps\lang1033\fs24 Omo\plain \f1\lang1033\fs24 , S. 269, Nr. 13. \endash  (171\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \u8250 \'9b\plain \f1\i\lang1033\fs24  Ad sanctum Andream\plain \f1\lang1033\fs24  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Oro te, beate Andrea, apostole et martyr Christi, intercede pro me}}\plain \f1\i\lang1033\fs24   ad dominum tuum, ut ipse, qui donauit tibi biduo\plain \f1\lang1033\fs24  ... Vgl. \plain \f1\scaps\lang1033\fs24 Wilmart\plain \f1\lang1033\fs24 , Manuel, S. 285, Nr. 43. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs24  Ad sanctum Stephanum\u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Obsecro te, beatissime Stephane, leuita et martyr Christi, ora pro me}}\plain \f1\i\lang1033\fs24   ad dominum nostrum Ihesum Christum\plain \f1\lang1033\fs24  ... Vgl. \plain \f1\scaps\lang1033\fs24 Wilmart\plain \f1\lang1033\fs24 , Manuel, S. 285, Nr. 46; \plain \f1\scaps\lang1033\fs24 Dell\plain \f1\scaps\lang1033\fs24 \rquote \plain \f1\scaps\lang1033\fs24 Omo\plain \f1\lang1033\fs24 , S. 272, Nr. 20.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Siglen: s. Abk\u252 \'fcrzungsverzeichnis. \endash  Weitere: \plain \f1\scaps\lang1033\fs20 Wilmart\plain \f1\lang1033\fs20 , Manuel = Andr\u233 \'e9 \plain \f1\scaps\lang1033\fs20 Wilmart\plain \f1\lang1033\fs20 , Le manuel de pri\u232 \'e8res de saint Jean Gualbert, in: RBen 48 (1936), S. 259-299. \endash  \plain \f1\scaps\lang1033\fs20 Turner\plain \f1\lang1033\fs20   = Derek Howard \plain \f1\scaps\lang1033\fs20 Turner\plain \f1\lang1033\fs20 , The prayer-book of archbishop Arnulph II of Milan, in: RBen 70 (1960), S. 360-392. \endash  \plain \f1\scaps\lang1033\fs20 Dell\plain \f1\scaps\lang1033\fs20 \rquote \plain \f1\scaps\lang1033\fs20 Omo\plain \f1\lang1033\fs20   = Mariano \plain \f1\scaps\lang1033\fs20 dell\plain \f1\scaps\lang1033\fs20 \rquote \plain \f1\scaps\lang1033\fs20 Omo\plain \f1\lang1033\fs20 , Nel raggio di Montecassino. Il \plain \f1\i\lang1033\fs20  libellus precum\plain \f1\lang1033\fs20   di S. Domenico di Sora (Vat. Reg. lat. 334), in: Classica et beneventana. Essays presented to Virginia Brown on the occasion of her 65th birthday. Hrsg. von Frank T. \plain \f1\scaps\lang1033\fs20 Coulson\plain \f1\lang1033\fs20   und Anna A. \plain \f1\scaps\lang1033\fs20 Grotans\plain \f1\lang1033\fs20 . Turnhout 2008 (Textes et \u233 \'e9tudes du Moyen \u194 \'c2ge 36), S. 235-291.}

