\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Precibus et meritis, domine sancte, pater omnipotens, eterne deus omnium sanctorum angelorum}}\plain \f1\i\lang1033\fs24   atque archangelorum Michahelis, Gabrielis, Raphahelis nouemque ordinum ciuium supernorum uirtutum\plain \f1\lang1033\fs24  ...\endash ... \plain \f1\i\lang1033\fs24  quatenus tuam uoluntatem adimplens in presenti seculo et in futuro cum sanctis omnibus, mererar sine fine gaudere\plain \f1\lang1033\fs24 . \endash  Mit Glosse, beschnitten (173\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): \plain \f1\i\lang1033\fs24  Dizze gebet\plain \f1\lang1033\fs24   [soltv] \plain \f1\i\lang1033\fs24  lesen gerne\plain \f1\lang1033\fs24   [daz] \plain \f1\i\lang1033\fs24  din\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  ende gvt\plain \f1\lang1033\fs24   [wer]\plain \f1\i\lang1033\fs24  de\plain \f1\lang1033\fs24 .}

