\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  16\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs22     {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Bernardinus Senensis (?)}}\plain \f1\b\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 De nomine Jesu}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs22  Incipit oracio beati Bernhardi de dulcissimo nomine Iesu\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O bone Iesu, o dulcis Iesu, o Iesu fili Marie uirginis}}\plain \f1\i\lang1033\fs22 , plenus miseriordia et pietate\plain \f1\lang1033\fs22  ...\endash ... \plain \f1\i\lang1033\fs22  ut possim te perfecte diligere et in te gloriari et delectari in secula seculorum. Amen\plain \f1\lang1033\fs22 . Vgl. \plain \f1\scaps\lang1033\fs22 Haimerl\plain \f1\lang1033\fs22 , S. 81, Anm. 474. \endash  \u8250 \'9b\plain \f1\i\lang1033\fs22  Versus\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Sit nomen domini benedictum}}\plain \f1\i\lang1033\fs22 , ex hoc nunc et usque in seculum\plain \f1\lang1033\fs22 . \endash  \u8250 \'9b\plain \f1\i\lang1033\fs22  Oremus\plain \f1\lang1033\fs22  \u8249 \'8b [D]\plain \f1\i\lang1033\fs22  eus, qui gloriosissimum nomen unigeniti filii tui domini nostri Iesu Cristi summo suauitatis affectu fidelibus fecisti amabile\plain \f1\lang1033\fs22   (CO 1645).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

