\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  -82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22     {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Viridarius de tempore}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs22  Incipit Viridarius de tempore\plain \f1\lang1033\fs22  \u8249 \'8b \endash  (1\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs22 ) \plain \f1\i\lang1033\fs22  Dominica prima in adventu\plain \f1\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ecce rex tuus, venit tibi (Mt 21,5). Quando aliquis rex vvlt intrare terram suam ob (!) inimicis inuasam}}\plain \f1\lang1033\fs22  ... \endash ... \plain \f1\i\lang1033\fs22  sic nobis faciet dominus, si hic eum recipimus\plain \f1\lang1033\fs22 . \endash  (1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  -2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  Dominica secunda in aduentu\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Tunc videbunt filium hominis (Lc 21,27). Nota quod septem pertinent ad iudicium}}\plain \f1\i\lang1033\fs22 , que eciam contingent in die iudicii\plain \f1\lang1033\fs22  ...\endash ... \plain \f1\i\lang1033\fs22  tunc ibunt hii in supplicium eternum, iusti autem in vitam eternam\plain \f1\lang1033\fs22   (Mt 25,46). \plain \f1\i\lang1033\fs22  Rogemus\plain \f1\lang1033\fs22 . \endash  (2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  -4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  De xv signis\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Erunt signa in sole et luna (Lc 21,25). In precedenti dominica recolimus de aduentu domini}}\plain \f1\i\lang1033\fs22   eius aduentum misericordie \plain \f1\lang1033\fs22 ...\endash ... \plain \f1\i\lang1033\fs22  venite, benedicti, quam uocem et inuitacionem donet nobis audire Ihesus Christus\plain \f1\lang1033\fs22 . \endash  (4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  -5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  Dominica tercia\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Cum audisset Iohannes in vinculis (Mt 11,2). Nota quod quando aliquis positus in turri}}\plain \f1\i\lang1033\fs22   et grauibus constrictus est uinculis septem facere consueuit\plain \f1\lang1033\fs22  ...\endash ... \plain \f1\i\lang1033\fs22  ut hec plaga cessauit, percussit enim angelus septuaginta milia de populo. Amen. Rogemus\plain \f1\lang1033\fs22 . \endash  (62\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  -64\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  Dominica vicesima quarta\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Mulier, que fluxum sangwinis paciebatur (Mt 9, 20). Septem sunt uirtutes, que sanant hominem in anima}}\plain \f1\lang1033\fs22  ... \endash ... \plain \f1\i\lang1033\fs22  et tangat sceptrum diuinitatis et ibi maneat mente et corpore\plain \f1\lang1033\fs22 . \endash  (64\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  Dominica xxv\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Cum subleuasset Ihesus (Io 6,5). Hodie uerbum delectabile dicitur, quia Ihesus Christus filius dei subleuatis}}\plain \f1\i\lang1033\fs22   oculis sanctissimis\plain \f1\lang1033\fs22  ... \endash ... \plain \f1\i\lang1033\fs22  et dirige actus tuos secundum dei uoluntatem. Rogemus dominum nostrum Ihesum Christum\plain \f1\lang1033\fs22 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Zu Druck und Lit. vgl. unten die Angaben zu 64\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20  -82\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  -82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22     {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Exempla ad Viridarium de tempore}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs22  Hic incipiunt exempla\plain \f1\lang1033\fs22 . \endash  (64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  -65\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  Exemplum. Dominica prima in aduentu domini\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Erat quedam uirgo nobilis xiiii annorum}}\plain \f1\i\lang1033\fs22 , que beate virgini erat valde deuota. Hec rogabat virginem gloriosam continue septem annis, ut ostendere sibi dignaretur filium suum\plain \f1\lang1033\fs22  ...\endash ... \plain \f1\i\lang1033\fs22  diligo te plus me, quia tu creasti, redemisti, dotasti me\plain \f1\lang1033\fs22 . Parallelhs.: Uppsala, UB, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 C 296}}\plain \f1\lang1033\fs22 , 85\plain \f1\super\lang1033\fs24 rv\plain \f1\lang1033\fs22 . \endash  (65\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  -65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  Dominica secunda. Exemplum\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Legitur enim, quod quidam nobilis erat magnus oppressor pauperum}}\plain \f1\i\lang1033\fs22   et amator mundi, hic dum, qui esset camerarius, iacens ante cameram rapitur in uisione ante thronum dei\plain \f1\lang1033\fs22  ...\endash ... \plain \f1\i\lang1033\fs22  narrata uisione ordinem cysterciensium intrauit\plain \f1\lang1033\fs22 . Vgl. Lajos \plain \f1\scaps\lang1033\fs22 Katona\plain \f1\lang1033\fs22 , Specimina et elenchus exemplorum quae in Pomerio sermonum quadragesimalium et de tempore fratris Pelbarti de Temesv\u225 \'e1r occurunt. Budapest 1903, S. 35, Nr. 235. \plain \f1\i\lang1033\fs22  \endash  \plain \f1\lang1033\fs22  Frederic C. \plain \f1\scaps\lang1033\fs22 Tubach\plain \f1\lang1033\fs22 , Index exemplorum. A handbook of medieval religious tales. Helsinki 1969 (FF Communications 204), Nr. 3481 \endash  (65\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  Dominica tercia\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Legitur in uitas patrum, quod quidam heremita orauit}}\plain \f1\i\lang1033\fs22 , ut uideret exitum anime a corpore et dum intraret ciuitatem vendere sportulas\plain \f1\lang1033\fs22  ...\endash ... \plain \f1\i\lang1033\fs22  quam accipiens deduxit in celum et in choro martyrum collocauit. Rogemus\plain \f1\lang1033\fs22 . \endash  (82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) \u8250 \'9b\plain \f1\i\lang1033\fs22  Dominica xxiiii\plain \f1\i\super\lang1033\fs24 a\plain \f1\lang1033\fs22  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Legitur in septimo libro ecclesiastice hystorie, quod beata Martha in memoriam sue curacionis}}\plain \f1\i\lang1033\fs22   affluxu fecit sibi sculpi ymaginem Ihesu Christi\plain \f1\lang1033\fs22  ...\endash ... \plain \f1\i\lang1033\fs22  quia ictu flaminis percussum est et herbarum vires recesserunt. Rogemus dominum, ut nos protegat ab omni malo\plain \f1\lang1033\fs22 . \endash  Schluss-Schrift: \u8250 \'9b{\field{\*\fldinst HYPERLINK "hida://5650[4].5686/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Explicit viridarius de tempore. Omnes sermones cum exemplis per totum annum per manus fratris Perchtoldi tunc temporis capellanus in Altenhohenaw anno domini m\u176 \'b0ccccxxi\u176 \'b0 proxima sexta feria post ascensionem domini}}\plain \f1\lang1033\fs22  \u8249 \'8b (= 2. Mai 1421). \endash  82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  -84\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22   leer, 84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22   bis auf zwei Federproben leer; ein Drittel von 84 beschnitten.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Parallelhs.: Berlin, SBB-PK, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Theol. lat. 4o 220}}\plain \f1\lang1033\fs20 , 134\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -171\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20   (andere Reihenfolge der \plain \f1\i\lang1033\fs20  exempla\plain \f1\lang1033\fs20 ). Vgl. auch Bamberg, SB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Msc. Theol. 158}}\plain \f1\lang1033\fs20 , 1\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -86\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , insbes. die dort \u252 \'fcberlieferten Schluss-Schriften, laut denen \plain \f1\i\lang1033\fs20  fratrer Albertus Raynoldi de kronach de bamberga ordinis fratrum predicatorum pro tunc capellanus jn altenhoenaw\plain \f1\lang1033\fs20   die Predigten 1440 abschrieb. \endash  Lit.: \plain \f1\scaps\lang1033\fs20 Schneyer\plain \f1\lang1033\fs20 , Beobachtungen, S. 34. \endash  \plain \f1\scaps\lang1033\fs20 Ders\plain \f1\lang1033\fs20 ., Wegweiser, S. 199, 245, 247. \endash  Zur Verfasserfrage vgl. Inventar der Handschriften des Benediktinerstiftes Melk. Bearb. von Christine \plain \f1\scaps\lang1033\fs20 Glassner\plain \f1\lang1033\fs20 . Teil 1: Von den Anf\u228 \'e4ngen bis ca. 1400. Wien 2000 (Denkschriften der \u246 \'f6sterreichischen Akademie der Wissenschaften. Philosophisch-Historische Klasse 285. Ver\u246 \'f6ffentlichungen der Kommission f\u252 \'fcr Schrift- und Buchwesen des Mittelalters 8,1,1), S. 417.}

