\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -64\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24     {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Cantica canticorum cum Glossa ordinaria}}
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 \plain \f1\lang1033\fs22  (1\plain \f1\super\lang1033\fs24 rab\plain \f1\lang1033\fs22 ) Prothema v: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Salomon, id est pacificus, quia in regno eius pax}}\plain \f1\i\lang1033\fs22 , per quam futura pax ecclesie figurabatur\plain \f1\lang1033\fs22   \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs22  et quem in his profecisse uident ad theoricam usque perducunt.\plain \f1\lang1033\fs22   \plain \f1\scaps\lang1033\fs22 Stegm\plain \f1\scaps\lang1033\fs22 \u252 \'fc\plain \f1\scaps\lang1033\fs22 ller\plain \f1\lang1033\fs22 , \plain \f1\scaps\lang1033\fs22 RB \plain \f1\scaps\lang1033\fs22 11804\plain \f1\super\scaps\lang1033\fs24 2\plain \f1\scaps\lang1033\fs22 ; \plain \f1\lang1033\fs22  Druck: \plain \f1\scaps\lang1033\fs22 Dove\plain \f1\lang1033\fs22 , S. 77 Z. 41-59. \endash  (1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 ) Prothema iv. \plain \f1\scaps\lang1033\fs22 Stegm\plain \f1\scaps\lang1033\fs22 \u252 \'fc\plain \f1\scaps\lang1033\fs22 ller, RB 11804\plain \f1\super\scaps\lang1033\fs24 6\plain \f1\scaps\lang1033\fs22 ; Dove\plain \f1\lang1033\fs22 , S. 75 Z. 33-40. \endash  (1\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22  -\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 ) Prothema ii. \plain \f1\scaps\lang1033\fs22 Stegm\plain \f1\scaps\lang1033\fs22 \u252 \'fc\plain \f1\scaps\lang1033\fs22 ller, RB 11804\plain \f1\super\scaps\lang1033\fs24 4-5\plain \f1\lang1033\fs22  ; \plain \f1\scaps\lang1033\fs22 Dove\plain \f1\lang1033\fs22 , S. 73 Z. 11-S. 75 Z. 22. \endash  (1\plain \f1\super\lang1033\fs24 vab\plain \f1\lang1033\fs22 ) Prothema i. \plain \f1\scaps\lang1033\fs22 Stegm\plain \f1\scaps\lang1033\fs22 \u252 \'fc\plain \f1\scaps\lang1033\fs22 ller, RB 11804\plain \f1\super\scaps\lang1033\fs24 7\plain \f1\lang1033\fs22  ; \plain \f1\scaps\lang1033\fs22 Dove\plain \f1\lang1033\fs22 , S. 73 Z. 1-10. \endash  (1\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22  -2\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 ) Prothema iii. \plain \f1\scaps\lang1033\fs22 Stegm\plain \f1\scaps\lang1033\fs22 \u252 \'fc\plain \f1\scaps\lang1033\fs22 ller, RB 11804\plain \f1\super\scaps\lang1033\fs24 9\plain \f1\lang1033\fs22  ; \plain \f1\scaps\lang1033\fs22 Dove\plain \f1\lang1033\fs22 , S. 75 Z. 25-32. \endash  (2\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs22 ) Prothema vi. \plain \f1\scaps\lang1033\fs22 Stegm\plain \f1\scaps\lang1033\fs22 \u252 \'fc\plain \f1\scaps\lang1033\fs22 ller, RB 11804\plain \f1\super\scaps\lang1033\fs24 3\plain \f1\lang1033\fs22  ; \plain \f1\scaps\lang1033\fs22 Dove\plain \f1\lang1033\fs22 , S. 77 Z. 60-S. 79 Z. 65. \endash  2\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs22   leer.
\par \pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa195\itap0 (2\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22  -64\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 ) Glossa marginalis: 1. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Synagoga, congregacio, quod et lapidum}}\plain \f1\lang1033\fs22   \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs22  consors effecta est\plain \f1\lang1033\fs22 . \plain \f1\scaps\lang1033\fs22 Stegm\plain \f1\scaps\lang1033\fs22 \u252 \'fc\plain \f1\scaps\lang1033\fs22 ller, RB 11804\plain \f1\super\scaps\lang1033\fs24 8\plain \f1\lang1033\fs22  ; \plain \f1\scaps\lang1033\fs22 Dove\plain \f1\lang1033\fs22 , S. 83 Z. 4-8. \endash  127. \u182 \'b6 \plain \f1\i\lang1033\fs22  Fuge dilecte\plain \f1\lang1033\fs22   (Ct 8,14). \plain \f1\i\lang1033\fs22  Quasi: tu quidem qui ex carne comprehensibilis factus es\plain \f1\lang1033\fs22   \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs22  quando id quod uolumus memoria non tenemus\plain \f1\lang1033\fs22 . \plain \f1\scaps\lang1033\fs22 Dove\plain \f1\lang1033\fs22 , S. 413 Z. 10-17.
