\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Zierinitialen in Deckfarben auf Goldgrund mit Zierranken}}\plain \f1\lang1033\fs20 : Buchstabenschaft jeweils in Blau, Rot oder Gr\u252 \'fcn, verziert mit Akanthusblattranken, 4\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20   auch mit Blattmasken, wei\u223 \'df oder gelb geh\u246 \'f6ht, zweifarbig gerahmt in der jeweiligen Gegenfarbe, Goldgrund gepunzt mit Rosetten, Sternbl\u252 \'fcten, Eicheln oder Kreisen; Seitenrahmung durch einen jeweils links positionierten Rankenstab, der sich an den \u252 \'fcbrigen Seitenr\u228 \'e4ndern zu Zierranken aus Akanthusbl\u228 \'e4ttern mit gefiederten Goldpollen verzweigt; Ranken verziert mit Bl\u252 \'fcten ({\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Akelei}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Nelken}}\plain \f1\lang1033\fs20 , Kornblumen, {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Distel}}\plain \f1\lang1033\fs20 ) und Fr\u252 \'fcchten ({\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Wein}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Erdbeeren}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Birnen}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Eicheln}}\plain \f1\lang1033\fs20 ), h\u228 \'e4ufig bewohnt von Tieren ({\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Affen}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5500[10]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hirsche}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5500[9]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 V\u246 \'f6gel}}\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5500[8]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hunde}}\plain \f1\lang1033\fs20 , Hasen) oder menschlichen Wesen (wilder Mann, {\field{\*\fldinst HYPERLINK "hida://5500[11]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Putto}}\plain \f1\lang1033\fs20 ).}

