\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22  60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  -63\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22     {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Martinus V. Papa}}\plain \f1\b\lang1033\fs22 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs22\chcbpat17 Confirmatio canonizationis beatae Birgittae}}
