\uc1
\pard\sl276\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs20\chcbpat17 Randzeichnung}}\plain \f1\scaps\lang1033\fs20 : (\plain \f1\lang1033\fs20  172\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 ), Durchmesser: 7,5; mehrfarbig lavierte Federzeichnung am Fu\u223 \'dfsteg: Medaillon mit {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Lamm Gottes, Siegesfahne}}\plain \f1\lang1033\fs20   und Kelch; Kreuznimbus in Gold; Umschrift: \plain \f1\i\lang1033\fs20  Agnus dei qui tollis peccata mundi miserere nobis.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

