\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 165\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -172\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Predigten zu Mariae Himmelfahrt}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24\cf1 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 (165\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -169\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 ) Predigt 1:\plain \f1\i\lang1033\fs24\cf1  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Wann der mensch als uns dy meister schreiben nach der bescheideheit}}\plain \f1\i\lang1033\fs24\cf1  und seiner inderlichen vernuft geistliche ding erchantnus nit mag gehaben \u8230 \'85 davon so han ich ein wart f\u252 \'fcr mich genumen daz stet geschriben in dem puch der zal \plain \f1\lang1033\fs24\cf1 \u8230 \'85\plain \f1\i\lang1033\fs24\cf1  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Auff erhaben ist dy wocken (!) von dem haus des glubs der freuntschaft \u8230 \'85 (Num. 9,17) \u8230 \'85 (165vb) Hye mugen wir mercken drey ding}}\plain \f1\i\lang1033\fs24\cf1 . Daz erst ist dy stat von der dy muter gotes genamen wart \plain \f1\lang1033\fs24\cf1 \u8230 \'85\endash \u8230 \'85\plain \f1\i\lang1033\fs24\cf1  als er mit seinem gehorsamen ist gewesen an dem anfang und nun und alweg und in dy ewigkeit der ewigkeit\plain \f1\lang1033\fs24\cf1 . \endash \plain \f1\i\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 (169\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1 -\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) Predigt 2:\plain \f1\b\lang1033\fs20\cf1  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Ein grosser meister gotlicher k\u252 \'fcnst wart gefragt}}\plain \f1\i\lang1033\fs24\cf1  waz unser liebe fraw gotes muter gethan hab da der engel zu ir cham. Er antwurt und sprach: si sass in einem leib unleiblich sy sas in einer zeyt unzeitlich \plain \f1\lang1033\fs24\cf1 \u8230 \'85\endash \u8230 \'85\plain \f1\i\lang1033\fs24\cf1  sy sas abgescheiden mit sel und leib von allem dem da\plain \f1\b\i\lang1033\fs20\cf1 z \plain \f1\i\lang1033\fs24\cf1 mit got nit waz\plain \f1\lang1033\fs24\cf1 . \endash \plain \f1\i\lang1033\fs24\cf1  \plain \f1\lang1033\fs24\cf1 (169\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 -172\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) Predigt 3:\plain \f1\b\i\lang1033\fs20\cf1  \plain \f1\i\lang1033\fs24\cf1 Wie gotes muter gelobt und geert wirt von ires hochsten suns wegen. {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1  Maria ist dy allerschonst lobreichist und ubertrefenlichist}}\plain \f1\i\lang1033\fs24\cf1 ymmerwerdent junckfrawlichest muter gotes\plain \f1\b\lang1033\fs20\cf1  \plain \f1\lang1033\fs24\cf1 \u8230 \'85\endash \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 daz wir erleucht werden in dem waren licht seiner gotlichen genaden seiner guldein inprinstigen kolen ferurier\plain \f1\lang1033\fs24\cf1  (!)\plain \f1\i\lang1033\fs24\cf1  s\u252 \'fcessester lieb seiner gepot und ler dardurch wir verdienen alles gut amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Courier New;}{\f3\fnil\fcharset186 Times New Roman;}{\f4\fnil\fcharset0 Junicode;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 173\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 -321\plain \f1\super\lang1033\fs24\cf1 va\plain \f1\lang1033\fs24\cf1    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Dietrich von Apolda}}\plain \f1\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17\cf1 Leben des hl. Dominicus, dt.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24\cf1 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Meinem gemintten in got Dietrichen von Apoldia}}\plain \f1\i\lang1033\fs24\cf1  des convencz czu Ertfurt gelegen in tewtscher provincie enpewtt ich pruder Munio maister des ordens \u8230 \'85 das ir ewch untterwindet czu dichtende die legende sant Dominicus\plain \f1\lang1033\fs24\cf1  \u8230 \'85 \endash  (173\plain \f1\super\lang1033\fs24\cf1 rb\plain \f1\lang1033\fs24\cf1 )\plain \f1\i\lang1033\fs24\cf1  Dem gemintten vatter seiner kind dem erwirdigen maister Nicolausen \u8230 \'85 wunsche ich pruder Diettrich von tewtscher provincien\plain \f1\lang1033\fs24\cf1 ... \endash  (175\plain \f1\super\lang1033\fs24\cf1 vb\plain \f1\lang1033\fs24\cf1 ) \plain \f1\i\lang1033\fs24\cf1 Hie vecht an die vorred ... {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 Multipharie multisque modis etc. Got der herr manigveltiglich}}\plain \f1\i\lang1033\fs24\cf1  und in manigerlay weis hat geladen sein au\u223 \'dferwelten \plain \f1\lang1033\fs24\cf1 ... \endash  (176\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 )\plain \f1\i\lang1033\fs24\cf1  Sant Gregorius spricht daz di\u223 \'dfer knecht sey prediger orden \plain \f1\lang1033\fs24\cf1 ... \endash  (177\plain \f1\super\lang1033\fs24\cf1 ra\plain \f1\lang1033\fs24\cf1 )\plain \f1\i\lang1033\fs24\cf1  Di\u223 \'df ist der anfang des lebens sancti Dominici. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17\cf1 G\u246 \'f6ttliche mynn von lawtern herczen von gutter gewissen}}\plain \f1\i\lang1033\fs24\cf1  mit stetter trew ...\endash \plain \f1\lang1033\fs24\cf1 \u8230 \'85 \plain \f1\i\lang1033\fs24\cf1 und czu dem iungsten schied er von di\u223 \'dfer welt da man czalt von Xps gepurt tausent und czwayhundert iar darnach in dem drew und neuczigsten\plain \f1\lang1033\fs24\cf1  (!)\plain \f1\i\lang1033\fs24\cf1  iar in dem andern herbstmonatt an dem tag den man nennet den funfften ydus. Also hat end das acht tayl di\u223 \'df puchs des lebens und der wunderwerck des hochgelobten vatters sancti Dominici.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Oberdeutsche \u220 \'dcbersetzung wie {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cgm 186}}\plain \f1\lang1033\fs20   und Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod III. 1.2\u176 \'b0 7}}\plain \f1\lang1033\fs20 . \endash  Vgl. Wolfgang \plain \f1\scaps\lang1033\fs20 Stammler\plain \f1\lang1033\fs20 , Mittelalterliche Prosa in deutscher Sprache, in: Deutsche Philologie im Aufriss 2\plain \f1\lang1033\fs20\cf1 . Unter\plain \f1\lang1033\fs20   Mitarbeit zahlreicher Fachgelehrter hrsg. von Wolfgang \plain \f1\scaps\lang1033\fs20 Stammler\plain \f1\lang1033\fs20 . 2., \u252 \'fcberarb. Aufl. Berlin 1960, Sp. 971, 1007. \endash  Werner \plain \f1\scaps\lang1033\fs20 Williams-Krapp\plain \f1\lang1033\fs20\cf1 , in: \u178 \'b2VL 2 (1980), Sp. 108f. (Hs. genannt).}

