\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24\cf1 I\plain \f2\super\lang1033\fs24\cf1 r\plain \f2\lang1033\fs24\cf1    {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\b\lang1033\fs24\chcbpat18\cf1 Brief der Schwester Margret M\u228 \'e4ndlin an ihre Base, Altenhohenau 1495}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24\cf1 (Oberrand weggeschnitten) ... \plain \f2\i\lang1033\fs24\cf1 dem puechel daz ir mir habt lassen schreiben gedenck ich mir es sey daz erst petel daz in dem puechel stet\plain \f2\lang1033\fs24\cf1 ...\endash \u8230 \'85 \plain \f2\i\lang1033\fs24\cf1 Datum an freytag nach liechtme\plain \f2\lang1033\fs24\cf1 [\u223 \'df] \plain \f2\i\lang1033\fs24\cf1 im LXXXXV jar\plain \f2\lang1033\fs24\cf1  (= 6. Februar 1495). \plain \f2\i\lang1033\fs24\cf1 Swester Margret M\u228 \'e4ndlin ewr p\u228 \'e4\u223 \'dfel closterfraw zu Altenhochenaw prediger orden.
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs20 Bitten der M. M\u228 \'e4ndlin an ihre ungenannte Base, die ein Gebetbuch f\u252 \'fcr Altenhohenau hat schreiben lassen, um Papier zum Abschreiben einer lat. Hs., um Wachs zu Kerzen und um Besorgung eines Briefs an ihre Schwester Magdalena in Regensburg. \endash  Margret M\u228 \'e4ndlin ist im Einnahmenbuch von Altenhohenau ({\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f2\lang1033\fs20\chcbpat18 Cgm 697}}\plain \f2\lang1033\fs20 ) zwischen 1509-13 als mume des \plain \f2\i\lang1033\fs20 doctor Peter Pawmgartner, kantzler zu Lanczhut\plain \f2\lang1033\fs20  genannt; zu Paumgartner vgl. Bosls Bayerische Biographie. 8000 Pers\u246 \'f6nlichkeiten aus 15 Jahrhunderten 1. Hrsg. von Karl \plain \f2\scaps\lang1033\fs20 Bosl\plain \f2\lang1033\fs20 . Regensburg 1983, S. 576. M\u246 \'f6glicherweise handelt es sich hier um einen Briefentwurf, nicht um den Originalbrief.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Courier New;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red224\green224\blue224;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24\cf1 l\plain \f2\super\lang1033\fs24\cf1 r\plain \f2\lang1033\fs24\cf1 -46\plain \f2\super\lang1033\fs24\cf1 v\plain \f2\lang1033\fs24\cf1    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\b\lang1033\fs24\chcbpat18\cf1 Birgitta von Schweden}}\plain \f2\b\lang1033\fs24\cf1 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f2\b\lang1033\fs24\chcbpat18\cf1 Regel des Birgittenordens, adaptierte Fassung, mit zugeh\u246 \'f6rigen Offenbarungen}}
\par \pard\fi0\li0\tx330\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24\cf1 
\par \pard\fi0\li0\tx330\ql\ri0\sb0\sa0\itap0 I\plain \f2\super\lang1033\fs24\cf1 rv\plain \f2\lang1033\fs24\cf1  leer. \endash  \plain \f2\i\lang1033\fs24\cf1 Hernach volget der anfangk des heiligen ordens genant salvatoris und die regel des ordens\plain \f2\lang1033\fs24\cf1 ... {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f2\i\lang1033\fs24\chcbpat18\cf1 In dem kunigreich Norbeden (!) und Sweden in der leczten herschafft des selben lands}}\plain \f2\lang1033\fs24\cf1  \u8230 \'85\endash \u8230 \'85 \plain \f2\i\lang1033\fs24\cf1 so wir\plain \f2\lang1033\fs24\cf1  (!) \plain \f2\i\lang1033\fs24\cf1 ichs volenden wan es mir gefelt oder gefallen wirdt\plain \f2\lang1033\fs24\cf1 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\i\lang1033\fs24\cf1 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs20 Vgl. Montag, \plain \f2\scaps\lang1033\fs20 Werk\plain \f2\lang1033\fs20 , S. 18, 60, 129-138, 140 Anm. 2, S. 212-243 (Edition der deutschen Fassung nach Hs. m 2, mit Lesarten aus dieser Hs.). \endash  Dietmar von \plain \f2\scaps\lang1033\fs20 Huebner\plain \f2\lang1033\fs20 , Zu Prozessionen und Ges\u228 \'e4ngen eines Processionale des 15. Jahrhunderts aus dem Birgittenorden, in: Festschrift Altom\u252 \'fcnster 1973. Hrsg. von Toni \plain \f2\scaps\lang1033\fs20 Grad\plain \f2\lang1033\fs20 . Aichach 1973, S. 81-130, ebd. S. 87, 109-111 (mit Textausz\u252 \'fcgen und Fundstellenbelegen aus dieser Hs.). \endash  Edition der lat. Fassung: Birgitta, Op. min. 1, ed. \plain \f2\scaps\lang1033\fs20 Eklund\plain \f2\lang1033\fs20 , S. 176-218.}

