\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24\cf1 68\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1 -74\plain \f1\super\lang1033\fs24\cf1 v\plain \f1\lang1033\fs24\cf1    {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18\cf1 Johannes von Kastl}}\plain \f1\b\lang1033\fs24\cf1  (Ps.-Albertus Magnus): {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat18\cf1 De fine religiosae perfectionis, dt.}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat18\cf1  (unvollst\u228 \'e4ndig)}}
