\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Holzdeckelband}}\plain \f1\lang1033\fs20   mit hellem Wildleder\u252 \'fcberzug; 1968 restauriert: Reste des urspr\u252 \'fcnglichen Leders \u252 \'fcber neuem angebracht. Metallschlie\u223 \'dfe, Beschlag auf dem Hinterdeckel mit eingepr\u228 \'e4gtem \plain \f1\i\lang1033\fs20  a\plain \f1\lang1033\fs20 . Beide Spiegel Papier. 2 Vorsatzbl\u228 \'e4tter und ein Nachsatzblatt Pergament: Liturgisches Fragment (Reimoffizium des hl. Wenzeslaus; AH 5 Nr. 96) mit {\field{\*\fldinst HYPERLINK "hida://5705[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Notation}}\plain \f1\lang1033\fs20   ({\field{\*\fldinst HYPERLINK "hida://5705[1]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Quadratnotation}}\plain \f1\lang1033\fs20  /{\field{\*\fldinst HYPERLINK "hida://5705[2]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hufnagelnotation}}\plain \f1\lang1033\fs20 ), 2. H\u228 \'e4lfte 14. Jh. oder 15. Jh. Auf der recto-Seite des Vorsatzes Federprobe, 2. H\u228 \'e4lfte 15. Jh.: \plain \f1\i\lang1033\fs20  die weil ich leb\plain \f1\lang1033\fs20 . Bl. 53 Palimpsest: vereinzelte W\u246 \'f6rter am Blattrand sichtbar, wohl 2. H\u228 \'e4lfte 14. Jh., liturgisch (?). 3 Blattweiser aus rotem Leder. \endash  Ungekl\u228 \'e4rte Buchstaben und Zahlen am unteren Blattrand 79\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : \plain \f1\i\lang1033\fs20  g\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20  87 M\plain \f1\lang1033\fs20 , \plain \f1\i\lang1033\fs20  97 p\plain \f1\lang1033\fs20 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Junicode;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -38\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24     {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Birgittinerregel, dt.}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24  Das erst capittel sant Saluators regel\plain \f1\lang1033\fs24  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Der anbegin diser gaistlichkeit vnd hails ist ware dem\u252 \'fctikeit}}\plain \f1\lang1033\fs24  ...\endash \u8230 \'85 \plain \f1\i\lang1033\fs24  vnd jn erden wider gewandelt sollen werden. Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 Die Schreiberkorrekturen lassen vermuten, dass es sich bei der Hs. um das Original der Verdeutschung der approbierten Regel handelt (\plain \f1\scaps\lang1033\fs24 Montag\plain \f1\lang1033\fs24 , Werk, S. 138). Weitere Korrekturen zielen auf eine m\u246 \'f6glichst getreue \u220 \'dcbersetzung des Originals hin ab (ebd. S. 138). Dass etliche Korrekturen dazu dienen, aus der adaptierten deutschen Fassung der Regel den Text der approbierten herzustellen, zeigt, dass in Gnadenberg die deutsche \u220 \'dcbersetzung der adaptierten Fassung vor der approbierten hergestellt worden ist (ebd. S. 136).
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Parallel\u252 \'fcberlieferung: Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod III.1.2\u176 \'b0 41}}\plain \f1\lang1033\fs20 , 5\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -27\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  ; einzelne Passagen aus dieser Hs. abgedruckt bei \plain \f1\scaps\lang1033\fs20 Montag\plain \f1\lang1033\fs20 , Werk, S. 245-247. \endash  Vgl. ebd., bes. S. 128-139 (mit Hinweis auf weitere \u220 \'dcberlieferung und Lit.). \endash  \plain \f1\scaps\lang1033\fs20 Montag\plain \f1\lang1033\fs20 , in: \plain \f1\super\lang1033\fs20 2\plain \f1\lang1033\fs20  VL 1 (1978), Sp. 869f. (Hs. genannt.). \endash  \plain \f1\scaps\lang1033\fs20 Ders\plain \f1\lang1033\fs20 ., The Reception of St Birgitta in Germany, in: Translation, ed. \plain \f1\scaps\lang1033\fs20 Morris\plain \f1\lang1033\fs20  /\plain \f1\scaps\lang1033\fs20 O\plain \f1\scaps\lang1033\fs20 \rquote \plain \f1\scaps\lang1033\fs20 Mara\plain \f1\lang1033\fs20 , bes. S. 107f.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Junicode;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  -72\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24     {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\b\lang1033\fs24\chcbpat17 Lucidarium f\u252 \'fcr die Nonnen des Birgittenordens}}
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \u8250 \'9b\plain \f1\i\lang1033\fs24  Hebet sich an ein vorrede vber das p\u252 \'fcchlein, daz do heist Elucidarius vnd sagt von der swestere obseruancie des ordens sant Saluators. Augustinus vber Johannem\plain \f1\lang1033\fs24  \u8249 \'8b {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Der g\u246 \'f6tlichen warheit vnd nyt der m\u-6588 ?nschen gewonheit}}\plain \f1\i\lang1033\fs24   schol vnd m\plain \f2\i\lang1033\fs24 \u-6355 ?\plain \f1\i\lang1033\fs24  \u223 \'df man nachfolgen. Wand es ist ein gro\u223 \'dfe hochfart\plain \f1\lang1033\fs24  ... \endash  (40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  Dorumb von pete wegen etlicher der eltisten swestere des closters zu Watzen\plain \f1\lang1033\fs24   (40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24  sant Saluators ordens hab ich dise gewonliche haltunge vnd satzunge z\plain \f2\i\lang1033\fs24 \u-6355 ?\plain \f1\i\lang1033\fs24   latein bracht mit fleisse, die auch dor nach z\plain \f2\i\lang1033\fs24 \u-6355 ?\plain \f1\i\lang1033\fs24   teutzsche gemacht sint in dem closter z\plain \f2\i\lang1033\fs24 \u-6355 ?\plain \f1\i\lang1033\fs24  m Gnadenberge des selben ordens\plain \f1\lang1033\fs24 . \u8250 \'9b\plain \f1\i\lang1033\fs24  Heben sich an die gesetz \plain \f1\lang1033\fs24 ...\u8249 \'8b \plain \f1\i\lang1033\fs24  Zv dem ersten\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24  Wan die swestere in yrem kore z\plain \f2\i\lang1033\fs24 \u-6355 ?\plain \f1\i\lang1033\fs24   samen komen, sch\u246 \'f6llen sy sich dem\u252 \'fcteclich gegen yrem altar neygen\plain \f1\lang1033\fs24  ...\endash \u8230 \'85 \plain \f1\i\lang1033\fs24  die mit der heiligen dreyualtekeit vnd allem himelschen her gelobt sey eweclich on ende von allen geschopfden. Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 
\par \pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs20  Parallel\u252 \'fcberlieferung: Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod III 1.2\u176 \'b0 41}}\plain \f1\lang1033\fs20 , 77\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  -124\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20 . \endash  Vgl. \plain \f1\scaps\lang1033\fs20 Montag\plain \f1\lang1033\fs20 , Werk, bes. S. 50f. (mit Hinweis auf weitere \u220 \'dcberlieferung und Lit.).}

